S.append(goals(c,B,['Mô tả <b>ngăn xếp (LIFO)</b> và <b>hàng đợi (FIFO)</b>.','Cài đặt ngăn xếp bằng <b>list</b> và hàng đợi bằng <b>collections.deque</b>.','Dùng ngăn xếp: <b>kiểm tra ngoặc</b>, <b>đảo xâu</b>, <b>tính biểu thức hậu tố</b>.','Dùng hàng đợi: <b>mô phỏng</b>, duyệt theo lớp.','Trace thao tác <b>push/pop, enqueue/dequeue</b>.'],['Ngăn xếp','Ứng dụng ngăn xếp','Hàng đợi','Ứng dụng hàng đợi','Trọng tâm, HSG']))
S.append(S2(c,B+' · 1','Ngăn xếp (stack): LIFO',card('Khái niệm',ul(['<b>Ngăn xếp</b>: thêm và lấy phần tử ở <b>cùng một đầu</b> (đỉnh).','Nguyên tắc <b>LIFO</b>: <b>vào sau, ra trước</b> (Last In, First Out).','Ví dụ: chồng đĩa, nút Back của trình duyệt, Undo.'],6)),RES('<svg viewBox="0 0 520 300" style="width:100%"><g font-family="monospace" font-weight="800" font-size="26" text-anchor="middle"><rect x="170" y="215" width="180" height="50" fill="#C5CAE9" stroke="#283593" stroke-width="3"/><text x="260" y="248" fill="#0B2545">5</text><rect x="170" y="160" width="180" height="50" fill="#C5CAE9" stroke="#283593" stroke-width="3"/><text x="260" y="193" fill="#0B2545">9</text><rect x="170" y="105" width="180" height="50" fill="#FFB300" stroke="#283593" stroke-width="3"/><text x="260" y="138" fill="#0B2545">2</text></g><path d="M100 60 L100 100" stroke="#2E7D32" stroke-width="6"/><path d="M85 85 L100 105 L115 85" fill="none" stroke="#2E7D32" stroke-width="6"/><text x="100" y="45" text-anchor="middle" font-size="24" font-weight="800" fill="#2E7D32">push</text><path d="M420 105 L420 60" stroke="#C62828" stroke-width="6"/><path d="M405 78 L420 58 L435 78" fill="none" stroke="#C62828" stroke-width="6"/><text x="420" y="45" text-anchor="middle" font-size="24" font-weight="800" fill="#C62828">pop</text><text x="260" y="95" text-anchor="middle" font-size="22" font-weight="800" fill="#0B2545">đỉnh (top)</text></svg>','Ngăn xếp')))
S.append(TB(c,B+' · 1','Các thao tác trên ngăn xếp',['Thao tác','Ý nghĩa','Với list s'],[['<b>push</b>','đẩy phần tử lên đỉnh','<code>s.append(x)</code>'],['<b>pop</b>','lấy và bỏ phần tử ở đỉnh','<code>s.pop()</code>'],['<b>top / peek</b>','xem đỉnh, không bỏ','<code>s[-1]</code>'],['<b>empty</b>','kiểm tra rỗng','<code>not s</code> hoặc <code>len(s) == 0</code>'],['<b>size</b>','số phần tử','<code>len(s)</code>']],mono=1,note=WARN('<b>pop trên ngăn xếp rỗng</b> gây <b>IndexError</b>: luôn kiểm tra rỗng trước.')))
S.append(PYR(c,B+' · 1','Ngăn xếp bằng list','s = []\ns.append(5)\ns.append(9)\ns.append(2)\nprint(s)\nprint(s.pop())\nprint(s[-1])\nprint(s, len(s))',KEY('Đầu <b>cuối</b> của list chính là <b>đỉnh</b> ngăn xếp: <code>append</code> và <code>pop()</code> đều <b>O(1)</b>.'),24))
S.append(PYR(c,B+' · 1','Trace push/pop','s = []\nfor x in [3, 1, 4]:\n    s.append(x)\n    print("push", x, "->", s)\nwhile s:\n    print("pop", s.pop(), "->", s)',KEY('Thứ tự ra <b>ngược</b> thứ tự vào: nhập 3, 1, 4 thì lấy ra 4, 1, 3.'),22))
S.append(PYR(c,B+' · 1','Đảo ngược xâu bằng ngăn xếp','def dao(s):\n    st = []\n    for ch in s:\n        st.append(ch)\n    kq = ""\n    while st:\n        kq += st.pop()\n    return kq\n\nprint(dao("Python"))\nprint(dao("abc") == "abc"[::-1])',KEY('Đẩy từng kí tự vào, rồi lấy ra: thứ tự bị <b>đảo</b>. Cách ngắn hơn là <code>s[::-1]</code>.'),22))
S.append(PYR(c,B+' · 2','Kiểm tra ngoặc hợp lệ','def hop_le(s):\n    st = []\n    cap = {")": "(", "]": "[", "}": "{"}\n    for ch in s:\n        if ch in "([{":\n            st.append(ch)\n        elif ch in ")]}":\n            if not st or st.pop() != cap[ch]:\n                return False\n    return not st\n\nfor t in ["(a+[b])", "(()", "([)]", ""]:\n    print(repr(t), hop_le(t))',KEY('Gặp ngoặc <b>mở</b>: push. Gặp ngoặc <b>đóng</b>: pop và so khớp. Cuối cùng ngăn xếp phải <b>rỗng</b>.'),19))
S.append(S2(c,B+' · 2','Trace kiểm tra ngoặc ([)]',CODE('chuỗi: ( [ ) ]',24),T(tr('Kí tự','Hành động','Ngăn xếp',h=True)+tr('(','push','(')+tr('[','push','( [')+tr(')','pop được [ ≠ (','→ sai'))+KEY('Gặp ")" nhưng đỉnh là "[" → <b>không khớp</b> → kết luận <b>không hợp lệ</b>.')))
S.append(S2(c,B+' · 2','Biểu thức hậu tố (RPN)',card('Ba cách viết biểu thức',ul(['<b>Trung tố</b>: <code>3 + 4</code>','<b>Hậu tố</b>: <code>3 4 +</code> (toán tử đứng sau)','<b>Tiền tố</b>: <code>+ 3 4</code>'],6)),KEY('Hậu tố <b>không cần ngoặc</b>: (3+4)*5 viết <code>3 4 + 5 *</code>.')+OK('Quy tắc tính: gặp <b>số</b> thì push; gặp <b>toán tử</b> thì pop hai số, tính rồi push kết quả.')))
S.append(PYR(c,B+' · 2','Tính biểu thức hậu tố','def tinh(bt):\n    st = []\n    for t in bt.split():\n        if t in "+-*/":\n            b = st.pop()\n            a = st.pop()\n            st.append(a + b if t == "+" else a - b if t == "-" else a * b if t == "*" else a / b)\n        else:\n            st.append(float(t))\n    return st[0]\n\nprint(tinh("3 4 + 5 *"))\nprint(tinh("5 1 2 + 4 * + 3 -"))',KEY('Chú ý thứ tự: <b>pop b trước, rồi a</b> (a là toán hạng trái). “5 1 2 + 4 * + 3 -” = 5 + (1+2)·4 − 3 = <b>14</b>.'),18))
S.append(S2(c,B+' · 3','Hàng đợi (queue): FIFO',card('Khái niệm',ul(['<b>Hàng đợi</b>: thêm ở <b>cuối</b>, lấy ở <b>đầu</b>.','Nguyên tắc <b>FIFO</b>: <b>vào trước, ra trước</b> (First In, First Out).','Ví dụ: xếp hàng mua vé, hàng chờ in, hàng đợi tiến trình.'],6)),RES('<svg viewBox="0 0 520 200" style="width:100%"><g font-family="monospace" font-weight="800" font-size="26" text-anchor="middle"><rect x="100" y="70" width="70" height="60" fill="#FFB300" stroke="#283593" stroke-width="3"/><rect x="170" y="70" width="70" height="60" fill="#C5CAE9" stroke="#283593" stroke-width="3"/><rect x="240" y="70" width="70" height="60" fill="#C5CAE9" stroke="#283593" stroke-width="3"/><rect x="310" y="70" width="70" height="60" fill="#C5CAE9" stroke="#283593" stroke-width="3"/><g fill="#0B2545"><text x="135" y="110">7</text><text x="205" y="110">3</text><text x="275" y="110">8</text><text x="345" y="110">1</text></g></g><path d="M80 100 L10 100 M25 85 L8 100 L25 115" fill="none" stroke="#C62828" stroke-width="6"/><text x="50" y="60" text-anchor="middle" font-size="22" font-weight="800" fill="#C62828">ra (front)</text><path d="M440 100 L385 100 M400 85 L383 100 M400 115 L383 100" fill="none" stroke="#2E7D32" stroke-width="6"/><text x="450" y="60" text-anchor="middle" font-size="22" font-weight="800" fill="#2E7D32">vào (rear)</text><text x="260" y="165" text-anchor="middle" font-size="22" font-weight="800" fill="#0B2545">đầu hàng ← … ← cuối hàng</text></svg>','Hàng đợi')))
S.append(PYR(c,B+' · 3','Hàng đợi bằng deque','from collections import deque\nq = deque()\nq.append(7)\nq.append(3)\nq.append(8)\nprint(q)\nprint(q.popleft())\nprint(q[0], len(q))\nprint(list(q))',KEY('<b>deque</b>: <code>append</code> thêm cuối, <code>popleft()</code> lấy đầu, đều <b>O(1)</b>.')+WARN('Dùng list với <code>pop(0)</code> mỗi lần tốn <b>O(n)</b> vì dồn mọi phần tử; dãy lớn nên dùng deque.'),22))
S.append(TB(c,B+' · 3','So sánh ngăn xếp và hàng đợi',['','Ngăn xếp','Hàng đợi'],[['Nguyên tắc','LIFO','FIFO'],['Thêm','cuối (đỉnh)','cuối (rear)'],['Lấy','cuối (đỉnh)','<b>đầu</b> (front)'],['Trong Python','list: append / pop()','deque: append / popleft()'],['Ứng dụng','ngoặc, hậu tố, đệ quy, Undo','mô phỏng, duyệt theo lớp (BFS), in ấn']],note=KEY('Cách nhớ: <b>stack = chồng đĩa</b> (lấy đĩa trên cùng); <b>queue = xếp hàng</b> (ai đến trước phục vụ trước).')))
